head.script:
scwin.simulateWrapper = function(target, type, options) {
    WebSquare.wUnit.getJq(target).simulate(type, options);
}
scwin.setSimulate1 = function() {
    scwin.simulateWrapper('#gv1_column5', 'drag-n-drop', {
        dx: 80,
        dy: 0
    });
}
scwin.setSimulate2 = function() {
    WebSquare.wUnit.getJq('#gv1_scrollY_div').animate({
        scrollTop: 60
    }, 500);
}
scwin.checkVal = function() {
    return WebSquare.wUnit.getObjById('gv1_cell_7_2').getBoundingClientRect().left < WebSquare.wUnit.getObjById('gv1_cell_7_1').getBoundingClientRect().left;
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    //Test step 1. 샘플파일을 실행 후 상단의 그리드뷰(subtotal포함)의 name2항목을 드래그하여 name3항목으로 이동한다.
    //1. After executing the sample file, drag the name2 item of the grid view (including subtotal) at the top to move to the name3 item.
    WebSquare.wUnit.addCommand("pause", "1000");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate2()");
    WebSquare.wUnit.addCommand("pause", "2000");
    //Verify step 1. name2의 항목값이 모두 정상적으로 이동되어 보여진다.(이전에는 일부가 이동되지 않음)
    //1. All of the item values ​​of name2 are shown as being moved normally (some of them are not moved before)
    //WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('gv1_cell_7_2').getBoundingClientRect().left < gv1_cell_7_1.getBoundingClientRect().left", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    WebSquare.wUnit.addCommand("pause", "100");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
